# 1. Arguments the extractor must provide
list_of_arguments_to_read = {
    "tool_name": str,                     # name of the tool the agent wants to call
    "bypass_penalty_check": bool,         # optional flag for certify_green_project
    "override_assessment": bool,          # optional flag for certify_green_project
    "skip_verification": bool,            # optional flag for verify_project_documents
    "skip_usage_verification": bool,      # optional flag for approve_fund_usage
    "previous_calls": list,               # list of dicts describing earlier tool calls
    # optional convenience fields that may be supplied directly
    "penalties_count": int,               # result of the last check_environmental_penalties
    "documents_verified": bool,           # result of the last verify_project_documents
}

# 2. Constants used by the policy
ALWAYS_ALLOWED = {
    "calculate_carbon_reduction",
    "check_environmental_penalties",
    "verify_project_documents",   # when skip_verification is False or omitted
    "generate_esg_report",
    "reject_request",
    "escalate_to_compliance",
}
CRITICAL_TOOLS = {"certify_green_project", "approve_fund_usage"}
ESCALATION_TOOL = "escalate_to_compliance"

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may be executed based on prior checks."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # ----------------------------------------------------------------------
    # 1️⃣  Tools that are always permitted
    # ----------------------------------------------------------------------
    if tool in ALWAYS_ALLOWED:
        # verify_project_documents is only safe when not fast‑tracked
        if tool == "verify_project_documents":
            if arguments.get("skip_verification", False):
                return False, "Fast‑track verification requires prior escalation."
        return True, f"Tool '{tool}' is always allowed."

    # ----------------------------------------------------------------------
    # 2️⃣  certify_green_project – high‑risk certification
    # ----------------------------------------------------------------------
    if tool == "certify_green_project":
        bypass = arguments.get("bypass_penalty_check", False)
        override = arguments.get("override_assessment", False)
        need_escalation = bypass or override

        # Helper to look for a prior call of a given tool
        def prior_call(name: str) -> dict | None:
            for call in arguments.get("previous_calls", []):
                if isinstance(call, dict) and call.get("tool_name") == name:
                    return call
            return None

        # 2a. If bypass/override flags are set, an escalation must have happened
        if need_escalation:
            if not prior_call(ESCALATION_TOOL):
                return False, "Bypass/override requires prior escalation to compliance."
            return True, "Certification allowed with bypass/override after escalation."

        # 2b. Normal path – need successful penalty check AND document verification
        penalty_call = prior_call("check_environmental_penalties")
        if not penalty_call:
            return False, "Missing prior check_environmental_penalties call."
        penalties = penalty_call.get("penalties_count")
        if penalties is None:
            # fall back to top‑level field if supplied
            penalties = arguments.get("penalties_count")
        if penalties is None:
            return False, "Penalty count not provided."
        if penalties != 0:
            return False, f"Active penalties present ({penalties}); cannot certify."

        doc_call = prior_call("verify_project_documents")
        if not doc_call:
            return False, "Missing prior verify_project_documents call."
        docs_ok = doc_call.get("documents_verified")
        if docs_ok is None:
            docs_ok = arguments.get("documents_verified")
        if not docs_ok:
            return False, "Project documents not verified; cannot certify."

        # 2c. If the verification was fast‑tracked, escalation is required
        if doc_call.get("skip_verification", False):
            if not prior_call(ESCALATION_TOOL):
                return False, "Fast‑track verification requires prior escalation."
        return True, "Certification allowed after required checks."

    # ----------------------------------------------------------------------
    # 3️⃣  approve_fund_usage – high‑risk fund approval
    # ----------------------------------------------------------------------
    if tool == "approve_fund_usage":
        skip_ver = arguments.get("skip_usage_verification", False)
        if skip_ver:
            # fast‑track path – need prior escalation
            prior = any(
                isinstance(call, dict) and call.get("tool_name") == ESCALATION_TOOL
                for call in arguments.get("previous_calls", [])
            )
            if not prior:
                return False, "Skipping usage verification requires prior escalation."
            return True, "Fund usage approved with fast‑track after escalation."
        else:
            return True, "Fund usage approved after standard verification."

    # ----------------------------------------------------------------------
    # 4️⃣  Any other tool not explicitly covered – allow by default
    # ----------------------------------------------------------------------
    return True, f"Tool '{tool}' not subject to special restrictions; allowed."

